package jlsm.table;

public enum IndexType {
    EQUALITY,
    RANGE,
    UNIQUE,
    FULL_TEXT,
    VECTOR
}

package jlsm.table;

import java.util.Objects;

import jlsm.core.indexing.SimilarityFunction;

public record IndexDefinition(String fieldName, IndexType indexType,
        SimilarityFunction similarityFunction) {

    public IndexDefinition(String fieldName, IndexType indexType) {
        this(fieldName, indexType, null);
    }

    public IndexDefinition {
        Objects.requireNonNull(fieldName, "fieldName");
        Objects.requireNonNull(indexType, "indexType");
        if (fieldName.isBlank()) {
            throw new IllegalArgumentException("fieldName must not be blank");
        }
        if (indexType == IndexType.VECTOR) {
            Objects.requireNonNull(similarityFunction,
                    "similarityFunction required for VECTOR indices");
        }
    }
}

package jlsm.table;

import java.util.List;
import java.util.Objects;

public sealed interface Predicate {

    record Eq(String field, Object value) implements Predicate {
        public Eq { Objects.requireNonNull(field); Objects.requireNonNull(value); }
    }

    record Ne(String field, Object value) implements Predicate {
        public Ne { Objects.requireNonNull(field); Objects.requireNonNull(value); }
    }

    record Gt(String field, Comparable<?> value) implements Predicate {
        public Gt { Objects.requireNonNull(field); Objects.requireNonNull(value); }
    }

    record Gte(String field, Comparable<?> value) implements Predicate {
        public Gte { Objects.requireNonNull(field); Objects.requireNonNull(value); }
    }

    record Lt(String field, Comparable<?> value) implements Predicate {
        public Lt { Objects.requireNonNull(field); Objects.requireNonNull(value); }
    }

    record Lte(String field, Comparable<?> value) implements Predicate {
        public Lte { Objects.requireNonNull(field); Objects.requireNonNull(value); }
    }

    record Between(String field, Comparable<?> low, Comparable<?> high) implements Predicate {
        public Between {
            Objects.requireNonNull(field);
            Objects.requireNonNull(low);
            Objects.requireNonNull(high);
        }
    }

    record FullTextMatch(String field, String query) implements Predicate {
        public FullTextMatch {
            Objects.requireNonNull(field);
            Objects.requireNonNull(query);
            if (query.isBlank()) throw new IllegalArgumentException("query must not be blank");
        }
    }

    record VectorNearest(String field, float[] queryVector, int topK) implements Predicate {
        public VectorNearest {
            Objects.requireNonNull(field);
            Objects.requireNonNull(queryVector);
            if (topK <= 0) throw new IllegalArgumentException("topK must be positive");
        }
    }

    record And(List<Predicate> children) implements Predicate {
        public And {
            Objects.requireNonNull(children);
            if (children.size() < 2) throw new IllegalArgumentException("And requires >= 2 children");
            children = List.copyOf(children);
        }
    }

    record Or(List<Predicate> children) implements Predicate {
        public Or {
            Objects.requireNonNull(children);
            if (children.size() < 2) throw new IllegalArgumentException("Or requires >= 2 children");
            children = List.copyOf(children);
        }
    }
}

